@@ -0,0 +1,111 @@
+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Collection;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+import java.util.stream.Collectors;
+
+/**
+ * What the backend narrows the customer list down to.
+ *
+ * <p>A customer matches when it satisfies both halves of the filter:
+ *
+ * <ul>
+ * <li><b>name</b> — every term must be a substring of the customer's first or
+ * last name, ignoring case and accents. No terms matches every customer.
+ * <li><b>status</b> — the customer's status must be one of the selected ones. An
+ * empty selection matches every customer.
+ * </ul>
+ *
+ * @param nameTerms the name terms, already {@linkplain #fold folded}; never null
+ * @param statuses  the accepted statuses, empty meaning "any"
+ */
+public record CustomerFilter(List<String> nameTerms, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter EMPTY = new CustomerFilter(List.of(), Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter(List<String> nameTerms, Set<CustomerStatus> statuses) {
+        // Terms are folded here so that a filter folds them once, not once per
+        // row it is matched against. Folding is idempotent, so a filter may be
+        // built either from raw or from already folded terms.
+        this.nameTerms = nameTerms.stream()
+                .map(CustomerFilter::fold)
+                .filter(term -> !term.isEmpty())
+                .toList();
+        this.statuses = statuses.isEmpty()
+                ? Set.of()
+                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+    }
+
+    /**
+     * Builds a filter from what the user typed and picked.
+     *
+     * @param nameText the raw filter text, split on whitespace into terms; may
+     *                 be null or blank
+     * @param statuses the selected statuses; may be null or empty
+     */
+    public static CustomerFilter of(String nameText, Collection<CustomerStatus> statuses) {
+        List<String> terms = (nameText == null || nameText.isBlank())
+                ? List.of()
+                : List.of(WHITESPACE.split(nameText.strip()));
+        Set<CustomerStatus> selected = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : EnumSet.copyOf(statuses);
+        return new CustomerFilter(terms, selected);
+    }
+
+    /** True when this filter accepts every customer. */
+    public boolean isEmpty() {
+        return nameTerms.isEmpty() && statuses.isEmpty();
+    }
+
+    /** True when {@code customer} passes both halves of this filter. */
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        if (nameTerms.isEmpty()) {
+            return true;
+        }
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        for (String term : nameTerms) {
+            if (!firstName.contains(term) && !lastName.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    /** The name terms as a single canonical string, terms separated by spaces. */
+    public String nameQuery() {
+        return String.join(" ", nameTerms);
+    }
+
+    /**
+     * Reduces text to what matching compares: lower case, accents removed.
+     *
+     * <p>So {@code makinen}, {@code MAKINEN} and {@code mäkinen} all fold to the
+     * same thing, which is what makes matching ignore case and accents in both
+     * directions.
+     */
+    public static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+
+    @Override
+    public String toString() {
+        return "CustomerFilter[name=" + nameQuery() + ", statuses="
+                + statuses.stream().map(CustomerStatus::name).collect(Collectors.joining(",")) + "]";
+    }
+}
